    // we'll work with the value as given, assuming the caller ensures it's valid
    let n_abs = n.abs() as u32; // Convert to u32 to handle digit extraction
    
    // Extract digits
    let hundreds = (n_abs / 100) % 10; // For numbers 100-127, this will be 1
    let tens = (n_abs / 10) % 10;
    let units = n_abs % 10;
    
